  "sources": "[\"https://fr.wikipedia.org/wiki/Gare_de_Versailles-Ch%C3%A2teau-Rive-Gauche\",\"https://fr.wikipedia.org/wiki/Gare_de_Vernon_-_Giverny\",\"https://fr.wikipedia.org/wiki/Giverny\",\"https://fr.wikipedia.org/wiki/Gare_de_Fontainebleau_-_Avon\",\"https://fr.wikipedia.org/wiki/Gare_de_Chantilly_-_Gouvieux\",\"https://fr.wikipedia.org/wiki/Gare_de_Provins\",\"https://fr.wikipedia.org/wiki/Gare_d%27Auvers-sur-Oise\",\"https://www.chateauversailles.fr\",\"https://fondation-monet.com\",\"https://www.chateaudefontainebleau.fr\",\"https://www.domainedechantilly.com\",\"https://provins.net\",\"https://maisondevangogh.fr\",\"https://www.sncf-connect.com\",\"https://www.iledefrance-mobilites.fr\",\"https://www.transilien.com\"]"
