  "glossary": "[{\"fr\":\"cuver\",\"cs\":\"nechat uzrát, odležet (obrazně)\"},{\"fr\":\"le doyen\",\"cs\":\"doyen, nejstarší člen\"},{\"fr\":\"prendre pour argent comptant\",\"cs\":\"brát za hotovou minci\"},{\"fr\":\"germer\",\"cs\":\"vyklíčit, zrodit se\"},{\"fr\":\"à proprement parler\",\"cs\":\"přesně vzato\"},{\"fr\":\"la teneur\",\"cs\":\"obsah, váha\"},{\"fr\":\"trôner\",\"cs\":\"trůnit\"},{\"fr\":\"le repaire\",\"cs\":\"doupě, oblíbené útočiště\"},{\"fr\":\"goûter (une anecdote)\",\"cs\":\"vychutnat si\"},{\"fr\":\"du bout des lèvres\",\"cs\":\"neochotně, jen přes zuby\"},{\"fr\":\"un regard en coin\",\"cs\":\"pohled úkosem\"},{\"fr\":\"le contrat tacite\",\"cs\":\"nepsaná dohoda\"},{\"fr\":\"à ciel ouvert\",\"cs\":\"pod širým nebem\"},{\"fr\":\"piquant (adj.)\",\"cs\":\"pikantní, zajímavý\"}]",
  "title_fr": "Les cafés littéraires de Paris : une table, un crayon, mille légendes",
