  "sources": "[\"https://www.prg.aero\",\"https://www.planes.cz/en/article/210646/smartwings-schedule-of-regular-flights-from-prague-for-summer-2026\",\"https://www.eea.europa.eu/publications/rail-and-waterborne-transport/rail-and-waterborne-best/\",\"https://impactco2.fr/outils/transport\",\"https://www.railwaypro.com/wp/obb-to-end-nightjet-services-to-paris-in-2025/\",\"https://www.railjournal.com/regions/europe/european-sleeper-launches-paris-berlin-night-train/\",\"https://www.europeansleeper.eu/paris\",\"https://www.seat61.com/international-trains/trains-from-Prague.htm\",\"https://www.omio.fr/bus/prague/paris\",\"https://europa.eu/youreurope/citizens/health/unplanned-healthcare/temporary-stays/index_en.htm\",\"https://www.service-public.gouv.fr/particuliers/actualites/A16577?lang=en\",\"https://mzv.gov.cz/paris/fr/service_consulaire/formalites_d_entree/formalite_d_enree.html\",\"https://www.iledefrance.fr/toutes-les-actualites/la-ligne-14-prolongee-met-laeroport-dorly-25-minutes-du-centre-de-paris\"]"
